var n=`1082-bulalo`;var s=`world-1082`;var a=`PH`;var t=`southeast-asia`;var o=4;var r=207;var l={en:`Bulalo`,ua:`Булало`};var g={en:`Bulalo is a dish from Philippines prepared with beef shank, beef marrow bones, yellow onion, potato. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Булало, страва кухні країни Філіппіни, яку готують із таких продуктів: яловича гомілка, мозкові яловичі кістки, жовта цибуля, картопля. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var h=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 180 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 180 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:180,i:[[`beef-shank`,900,`g`],[`beef-marrow-bones`,850,`g`],[`water`,2200,`ml`],[`yellow-onion`,200,`g`],[`black-peppercorn`,9,`pcs`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 22 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 22 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:22,i:[[`potato`,320,`g`],[`white-cabbage`,300,`g`],[`green-beans`,210,`g`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:3,i:[[`fish-sauce`,35,`ml`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`green-onion`,30,`g`]]}];var m={slug:n,id:s,country:`PH`,region:t,servings:4,minutes:207,title:l,text:g,steps:h};export{a as country,m as default,s as id,r as minutes,t as region,o as servings,n as slug,h as steps,g as text,l as title};